class Solution {
public:
    vector<vector<int>> colorRed(int n) {
        vector<vector<int>> ans(1, vector<int>{1, 1});
        for (int row=n, phase=0; row>1; --row, phase=(phase+1)%4) {
            if (phase==0) {
                for(int col=1;col<2*row;col+=2) ans.push_back({row,col});
            } else if (phase==1) {
                ans.push_back({row,2});
            } else if (phase==2) {
                for(int col=3;col<2*row;col+=2) ans.push_back({row,col});
            } else {
                ans.push_back({row,1});
            }
        }
        return ans;
    }
};
